package ro.leo.visual;
import ro.leo.i18n.L;import android.content.*;import android.net.Uri;import android.app.DownloadManager;import org.json.*;import java.io.*;import java.util.*;
public final class FeedsActivity extends PocketActivity {
 private boolean podcast(){return getIntent().getBooleanExtra("podcast",false);}private String title(){return podcast()?L.t("Podcasturi Leo"):L.t("Știri Leo");}
 protected void render()throws Exception{if(podcast())PodcastDownloads.reconcile(this);final JSONObject state=PocketStore.read(this,"feeds");final JSONArray feeds=state.optJSONArray("feeds")==null?new JSONArray():state.getJSONArray("feeds");final ArrayList<JSONObject> visible=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();labels.add(L.t("Adaugă abonament"));labels.add(podcast()?L.t("Episoade descărcate"):L.t("Articole salvate"));for(int i=0;i<feeds.length();i++){JSONObject f=feeds.getJSONObject(i);if(f.optBoolean("podcast")==podcast()){visible.add(f);labels.add(f.optString("name")+"\n"+f.optString("url"));}}list(title(),labels,0,new Choice(){public void pick(int at){if(at==0)add();else if(at==1){if(podcast())downloads();else saved();}else items(visible.get(at-2));}},L.t("Salvare"),new Runnable(){public void run(){startActivity(new Intent(FeedsActivity.this,StorageSettingsActivity.class));}});}
 private void add(){edit(L.t("Abonament nou"),new String[]{L.t("Nume"),L.t("Adresă RSS / Atom")},new String[]{"","https://"},new Saved(){public void save(String[] v)throws Exception{String url=PocketStore.url(v[1]);if(v[0].trim().isEmpty())throw new IOException("Name required");JSONObject state=PocketStore.read(FeedsActivity.this,"feeds");JSONArray rows=state.optJSONArray("feeds");if(rows==null)rows=new JSONArray();if(rows.length()>=40)throw new IOException("Maximum 40 feeds");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optString("url").equals(url)&&rows.getJSONObject(i).optBoolean("podcast")==podcast())throw new IOException("Already subscribed");rows.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("name",v[0].trim()).put("url",url).put("podcast",podcast()));state.put("feeds",rows);PocketStore.write(FeedsActivity.this,"feeds",state);home();}},goHome());}
 private void items(final JSONObject feed){try{final JSONObject cache=PocketStore.read(this,"feed-"+feed.getString("id"));final JSONArray rows=cache.optJSONArray("items")==null?new JSONArray():cache.getJSONArray("items");ArrayList<String> labels=new ArrayList<>();for(int n=0;n<rows.length();n++){JSONObject item=rows.getJSONObject(n);if(podcast()&&item.optString("audio").isEmpty())continue;labels.add(item.optString("title")+"\n"+UiText.preview(item.optString("body"),90));}final ArrayList<JSONObject> shown=new ArrayList<>();for(int n=0;n<rows.length();n++)if(!podcast()||!rows.getJSONObject(n).optString("audio").isEmpty())shown.add(rows.getJSONObject(n));list(feed.optString("name"),labels,0,new Choice(){public void pick(int at){article(feed,shown.get(at));}},L.t("Actualiz."),new Runnable(){public void run(){refresh(feed);}});back=goHome();if(rows.length()==0)notice(L.t("Actualizează pentru prima descărcare"));rightOptions(feed);}catch(Exception e){problem(e);}}
 private void rightOptions(final JSONObject feed){final Runnable refresh=left;left=new Runnable(){public void run(){options(title(),new String[]{L.t("Actualizează abonamentul"),L.t("Șterge abonamentul")},new Choice(){public void pick(int at){if(at==0)refresh.run();else remove(L.t("Ștergi abonamentul?"),new Runnable(){public void run(){try{JSONObject state=PocketStore.read(FeedsActivity.this,"feeds");JSONArray old=state.getJSONArray("feeds"),next=new JSONArray();for(int n=0;n<old.length();n++)if(!old.getJSONObject(n).optString("id").equals(feed.optString("id")))next.put(old.get(n));state.put("feeds",next);PocketStore.write(FeedsActivity.this,"feeds",state);home();}catch(Exception e){problem(e);}}});}});}};footer(L.t("Opțiuni"),L.t("Deschide"),L.t("Înapoi"));}
 private void refresh(final JSONObject feed){job(L.t("Actualizez abonamentul"),new Work(){public void run()throws Exception{String url=feed.getString("url");JSONArray items=PocketFeeds.parse(PocketFeeds.fetch(url),url);PocketStore.write(FeedsActivity.this,"feed-"+feed.getString("id"),new JSONObject().put("items",items).put("updated",System.currentTimeMillis()));}},new Runnable(){public void run(){items(feed);}});}
 private void article(final JSONObject feed,final JSONObject item){page(item.optString("title"),item.optString("body",L.t("Fără descriere")),feed==null?new Runnable(){public void run(){saved();}}:new Runnable(){public void run(){items(feed);}},L.t("Opțiuni"),new Runnable(){public void run(){options(item.optString("title"),podcast()?new String[]{L.t("Ascultă episodul"),L.t("Descarcă episodul"),L.t("Deschide pagina")}:new String[]{L.t("Salvează articolul"),L.t("Deschide pagina")},new Choice(){public void pick(int at){try{if(podcast()&&at==0){play(item.optString("audio"),item.optString("title"));}else if(podcast()&&at==1)download(item);else if(!podcast()&&at==0){JSONObject s=PocketStore.read(FeedsActivity.this,"saved-news");JSONArray rows=s.optJSONArray("items");if(rows==null)rows=new JSONArray();for(int n=0;n<rows.length();n++)if(rows.getJSONObject(n).optString("key").equals(item.optString("key"))){notice(L.t("Deja salvat"));return;}if(rows.length()>=100)throw new IOException("Maximum 100 saved articles");rows.put(item);PocketStore.write(FeedsActivity.this,"saved-news",s.put("items",rows));notice(L.t("Salvat"));}else startActivity(new Intent(FeedsActivity.this,BrowserActivity.class).setData(Uri.parse(PocketStore.url(item.optString("link")))));}catch(Exception e){problem(e);}}});}});}
 static void play(Context c,String url,String name)throws Exception{String checked=PocketStore.url(url);c.startForegroundService(new Intent(c,PlaybackService.class).setData(Uri.parse(checked)).putExtra("title",name));c.startActivity(new Intent(c,NowPlayingActivity.class));}
 private void play(String url,String name)throws Exception{play(this,url,name);}
 static DownloadManager.Request downloadRequest(String url,String name,File target)throws Exception{return new DownloadManager.Request(Uri.parse(PocketStore.url(url))).setTitle(UiText.preview(name,100)).setDestinationUri(Uri.fromFile(target)).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);}
 private void download(final JSONObject item){options(L.t("Descarci episodul?"),new String[]{L.t("Anulează"),L.t("Descarcă · poate folosi date mobile")},new Choice(){public void pick(int yes){if(yes!=1)return;try{String url=PocketStore.url(item.optString("audio"));String ext=Uri.parse(url).getPath().toLowerCase(Locale.ROOT).endsWith(".m4a")?".m4a":".mp3";File target=new File(PocketStore.podcastFolder(FeedsActivity.this),System.currentTimeMillis()+"-"+UUID.randomUUID()+ext);long id=PodcastDownloads.enqueue(FeedsActivity.this,url,item.optString("title"),target);notice(L.t("Descărcare programată")+" · "+id);}catch(Exception e){problem(e);}}});}
 private void downloads(){try{PodcastDownloads.reconcile(this);final JSONArray jobs=PodcastDownloads.jobs(this);ArrayList<String> labels=new ArrayList<>();labels.add(L.t("Fișiere salvate"));labels.add(L.t("Reîncearcă salvarea pe card"));for(int n=jobs.length()-1;n>=0;n--){JSONObject j=jobs.getJSONObject(n);labels.add(j.optString("title")+"\n"+PodcastDownloads.label(j.optString("status"))+(j.optString("error").isEmpty()?"":" · "+j.optString("error")));}list(L.t("Episoade descărcate"),labels,0,new Choice(){public void pick(int at){if(at==0)try{startActivity(new Intent(FeedsActivity.this,FilesActivity.class).putExtra("folder",PocketStore.podcastFolder(FeedsActivity.this).getPath()));}catch(Exception e){problem(e);}else if(at==1){PodcastDownloads.reconcile(FeedsActivity.this);notice(L.t("Salvare cerută"));}else try{final JSONObject j=jobs.getJSONObject(jobs.length()-1-(at-2));final long id=j.getLong("id");if("ready".equals(j.optString("status"))){final File file=new File(j.getString("destination"));options(j.optString("title"),new String[]{L.t("Ascultă"),L.t("Fișiere")},new Choice(){public void pick(int which){try{if(which==0){startForegroundService(new Intent(FeedsActivity.this,PlaybackService.class).setData(LeoFileProvider.uri(FeedsActivity.this,file)).putExtra("title",j.optString("title")));startActivity(new Intent(FeedsActivity.this,NowPlayingActivity.class));}else startActivity(new Intent(FeedsActivity.this,FilesActivity.class).putExtra("folder",file.getParent()).putExtra("select_file",file.getPath()));}catch(Exception e){problem(e);}}});}else options(PodcastDownloads.label(j.optString("status")),new String[]{L.t("Actualiz."),L.t("Reîncearcă salvarea pe card"),L.t("Anulează descărcarea")},new Choice(){public void pick(int which){if(which==0)downloads();else if(which==1)PodcastDownloads.request(FeedsActivity.this,id);else remove(L.t("Anulezi descărcarea?"),new Runnable(){public void run(){try{((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).remove(id);PodcastDownloads.forget(FeedsActivity.this,id);downloads();}catch(Exception e){problem(e);}}});}});}catch(Exception e){problem(e);}}},L.t("Actualiz."),new Runnable(){public void run(){downloads();}});back=goHome();}catch(Exception e){problem(e);}}
 private void saved(){try{JSONObject data=PocketStore.read(this,"saved-news");final JSONArray rows=data.optJSONArray("items")==null?new JSONArray():data.getJSONArray("items");ArrayList<String> labels=new ArrayList<>();for(int n=0;n<rows.length();n++)labels.add(rows.getJSONObject(n).optString("title"));list(L.t("Articole salvate"),labels,0,new Choice(){public void pick(int at){try{article(null,rows.getJSONObject(at));}catch(Exception e){problem(e);}}},L.t("Șterge tot"),new Runnable(){public void run(){remove(L.t("Ștergi articolele salvate?"),new Runnable(){public void run(){try{PocketStore.write(FeedsActivity.this,"saved-news",new JSONObject());saved();}catch(Exception e){problem(e);}}});}});back=goHome();}catch(Exception e){problem(e);}}
}
